  lead: "أدخل أموالك الزكوية (نقد، ذهب، فضة، عروض تجارة، ديون متوقعة) وسعر جرام الفضة، فتُظهر لك الحاسبة إجمالي الوعاء والنصاب ومقدار الزكاة ٢٫٥٪ والحكم بلغة واضحة — مجانية ومحليّة بلا تسجيل.",
  cta: [{ t: "💰 احسب زكاتك الآن", h: "/#/tool/zakat" }, { t: "📖 حاسبة المواريث", h: "/#/tool/mawarith" }],
  badges: ["2.5%", "نصاب 85غ فضة", "حفظ محلي", "مجاني"],
  body: `
  <section class="lp-sec">
    <h2>كيف تحسب الحاسبة؟</h2>
    <ul>
      <li><b>الوعاء الزكوي</b> = النقد والحسابات البنكية + قيمة الذهب + قيمة الفضة + عروض تجارة + الديون المتوقعة التحصيل.</li>
      <li><b>النصاب</b> = ٨٥ غرامًا من الفضة × سعر الغرام اليوم (تُحدّده أنت فتتحدّث النتيجة تلقائيًا).</li>
      <li><b>الزكاة</b> = ٢٫٥٪ من الوعاء إذا بلغ النصاب وحال عليه الحول.</li>
    </ul>
    <h3>مثال رقمي</h3>
    <p>لديك ١٠٬٠٠٠ جنيه نقدًا وسعر جرام الفضة ١٠٠ جنيه ← النصاب = ٨٥ × ١٠٠ = <b>٨٬٥٠٠</b> ← بلغت النصاب ← الزكاة = ١٠٬٠٠٠ × ٢٫٥٪ = <b>٢٥٠ جنيه</b>. ولو كان النقض ٥٬٠٠٠ فقط ← لم يبلغ النصاب ← لا زكاة عليه بعد.</p>
  </section>
  <section class="lp-sec">
    <h2>ملاحظات فقهية مهمة</h2>
    <ul>
      <li>الذهب يُقدَّر بوزنه الفعلي مطروحًا منه ما تستخدمه منه زينةً؟ — الراجح زكات الذهب ما بلغ النصاب وحال عليه الحول استعمالًا كان أو زينة.</li>
      <li>عروض التجارة تُزكّى بقيمتها السوقية لا بالسعر المدفوع.</li>
      <li>الديون إن كان تحصيلها متيقنًا تُحسب، وإن كانت ميؤوسًا منها لا.</li>
      <li><b>تنبيه</b>: هذه الحاسبة أداة إرشادية مبنية على أعداد نصاب الفضة المتفق عليها؛ ومسائل الزكاة تختلف بحسب أحوال المسألة — فراجع أهل العلم لمسألة بعينها.</li>
    </ul>
  </section>  `,
