  lead: "من الصفر إلى أول نشر: المقاسات الصحيحة لكل منصّة، اختيار الآية والقارئ والخلفية، أدوات الإخراج، ثم آداب النشر وحقوق التلاوة — في صفحة واحدة.",
  cta: [{ t: "🎬 ابدأ التنفيذ", h: "/ar/quran-video-maker/" }, { t: "📊 المقارنة", h: "/ar/compare/quran-video-makers/" }],
  badges: ["خطوات عملية", "مقاسات جاهزة", "آداب + حقوق"],
  body: `
  <section class="lp-sec">
    <h2>1) المقاسات</h2>
    <table class="tbl">
      <tr><th>المنصّة</th><th>المقاس</th><th>مدة مقترحة</th></tr>
      <tr><td>تيك توك / شورتس / ريلز</td><td><b>9:16</b> (1080×1920)</td><td>15-60 ثانية</td></tr>
      <tr><td>منشور خلاصة إنستغرام/فيسبوك</td><td>1:1</td><td>30-60 ثانية</td></tr>
      <tr><td>حالات واتساب</td><td>9:16</td><td>30 ثانية مريحة</td></tr>
      <tr><td>عرض أفقي/يوتيوب</td><td>16:9</td><td>حتى5 دقائق</td></tr>
    </table>
    <h2>2) اختيار المحتوى</h2>
    <ul>
      <li><b>قصار المصلّى</b>أقصر الآيات لأعلى اكتمال مشاهدة — <a href="/ar/short-quran-verses-video/">قائمتها</a>.</li>
      <li><b>القارئ</b>حسب جمهورك من <a href="/ar/best-quran-reciters-video/">دليل الأصوات</a>.</li>
      <li><b>الموضوع</b>يوميات التدبّر من <a href="/ar/ayat-bil-mawdoo/">آيات بالموضوع</a>.</li>
      <li><b>الموسم</b>خطّط قبله من <a href="/blog/ramadan-content-plan/">خطة رمضان</a> و<a href="/blog/friday-content/">محتوى الجمعة</a>.</li>
    </ul>
    <h2>3) الإخراج</h2>
    <ul>
      <li>نصّ واضح بخط كبير (الوضع «عريض») + تباين عالٍ، أو <a href="/ar/quran-word-highlight-video/">تظليل الكلمات</a>.</li>
      <li>خلفية ثابتة أو هادئة —14 خيارًا جاهزة، <b>بلا موسيقى</b> اختيارك.</li>
      <li>ترجمة8 لغات إن كان جمهورك عالميًا.</li>
      <li>تصدير بلا علامة مائية ثم تدقيق: اقرأ النص9 مرات قبل النشر (خطأ الآية لا يغتفر).</li>
    </ul>
    <h2>4) آداب النشر وحقوق التلاوات</h2>
    <ul>
      <li><b>تنويه المصدر</b>اذكر اسم القارئ والسورة في الوصف — وبإمكانك رابط المصدر الصوتي الأصلي.</li>
      <li><b>لا يُنسب للقرآن ما ليس منه</b>ولا تُقطّع آية بمعانٍ مقلوبة — وراجع <a href="/ar/quran-tafsir-video/">ضوابط التفسير</a>.</li>
      <li><b>حقوق التلاوة</b>لكل صوت شروطه ومعموله المعلن — التزام بشروط المصدر عند النشر خيرٌ سُنّة.</li>
      <li><b>الامانة</b>أي آية مع رسم محرَّف = أعد التصدير قبل النشر.</li>
    </ul>
    <h2>5) النشر</h2>
    <p>جدولة يدوية أو أتمتة يومية مع كتابة الوصف والوسوم — <a href="/blog/schedule-quran-reels/">دليل الجدولة</a>.</p>
  </section>`,
