let n = 0;
for (const p of PAGES) {
  const dir = path.join(__dirname, "..", "public", p.base !== undefined ? p.base : "ar", p.slug);
  fs.mkdirSync(dir, { recursive: true });
  fs.writeFileSync(path.join(dir, "index.html"), page(p));
  n++;
  console.log("wrote", p.slug, fs.statSync(path.join(dir, "index.html")).size, "bytes");
}
console.log("total pages:", n);
